B.aZs={"\u0627\u062e\u062a\u0628\u0627\u0631 \u0628\u0631\u0648\u0643\u062a\u0648\u0631 \u0627\u0644\u0642\u064a\u0627\u0633\u064a":0,"\u0627\u062e\u062a\u0628\u0627\u0631 \u0628\u0631\u0648\u0643\u062a\u0648\u0631 \u0627\u0644\u0645\u0639\u062f\u0651\u0644":1,"\u0627\u0644\u0648\u0632\u0646 \u0627\u0644\u0646\u0648\u0639\u064a \u0644\u0644\u062a\u0631\u0628\u0629":2,"\u0627\u0644\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0645\u0627\u0626\u064a \u0644\u0644\u062a\u0631\u0628\u0629":3,"\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u062d\u0642\u0644\u064a\u0629 \u0628\u0637\u0631\u064a\u0642\u0629 \u0645\u062e\u0631\u0648\u0637 \u0627\u0644\u0631\u0645\u0644":4,[u.J]:5,"\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u062a\u0631\u0628\u0629 \u0628\u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0645\u0648\u062d\u062f USCS":6,"\u062a\u0635\u0646\u064a\u0641 \u0627\u0644\u062a\u0631\u0628\u0629 \u0628\u0646\u0638\u0627\u0645 AASHTO":7,"\u062d\u062f\u0648\u062f \u0623\u062a\u0631\u0628\u0631\u062c: \u0627\u0644\u0633\u064a\u0648\u0644\u0629 \u0648\u0627\u0644\u0644\u062f\u0648\u0646\u0629":8,"\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0646\u062e\u0644\u064a \u0648\u0627\u0644\u062a\u062f\u0631\u062c \u0627\u0644\u062d\u0628\u064a\u0628\u064a":9,"\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0628\u0627\u0644\u0647\u064a\u062f\u0631\u0648\u0645\u064a\u062a\u0631":10,"\u0627\u0644\u062a\u062f\u0631\u062c \u0628\u0639\u062f \u0627\u0644\u0627\u0633\u062a\u062e\u0644\u0627\u0635":11,"\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0634\u062f \u0628\u0627\u0644\u0627\u0646\u0634\u0637\u0627\u0631":12,"\u0627\u0633\u062a\u062e\u0644\u0627\u0635 \u0627\u0644\u0628\u064a\u062a\u0648\u0645\u064a\u0646":13,"\u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0627\u062e\u062a\u0631\u0627\u0642":14,"\u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0644\u0632\u0648\u062c\u0629":15,"\u0627\u062e\u062a\u0628\u0627\u0631 \u0646\u0642\u0637\u0629 \u0627\u0644\u0644\u064a\u0648\u0646\u0629":16,"\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0636\u063a\u0637 \u0644\u0644\u0645\u0643\u0639\u0628\u0627\u062a \u0648\u0627\u0644\u0623\u0633\u0637\u0648\u0627\u0646\u0627\u062a":17,"\u0627\u062e\u062a\u0628\u0627\u0631 \u0627\u0644\u0647\u0628\u0648\u0637 Slump":18,"\u0645\u0642\u0627\u0648\u0645\u0629 \u0627\u0644\u0627\u0646\u062d\u0646\u0627\u0621":19,"\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0648\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0647\u0648\u0627\u0621":20,"\u0645\u062d\u062a\u0648\u0649 \u0627\u0644\u0647\u0648\u0627\u0621 \u0628\u0627\u0644\u0636\u063a\u0637 \u0644\u0644\u062e\u0631\u0633\u0627\u0646\u0629 \u0627\u0644\u0637\u0627\u0632\u062c\u0629":21,[u.m]:22,"\u0627\u062e\u062a\u0628\u0627\u0631 \u0645\u0627\u0631\u0634\u0627\u0644":23,"\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u0635\u0627\u0635":24,[u.k]:25,"\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u0635\u0627\u0635 \u0644\u0644\u0631\u0643\u0627\u0645 \u0627\u0644\u062e\u0634\u0646":26,"\u0627\u0644\u0643\u062b\u0627\u0641\u0629 \u0627\u0644\u0646\u0648\u0639\u064a\u0629 \u0648\u0627\u0644\u0627\u0645\u062a\u0635\u0627\u0635 \u0644\u0644\u0631\u0643\u0627\u0645 \u0627\u0644\u0646\u0627\u0639\u0645":27,"\u0627\u0644\u062a\u062d\u0644\u064a\u0644 \u0627\u0644\u0645\u0646\u062e\u0644\u064a \u0644\u0644\u0631\u0643\u0627\u0645 \u0627\u0644\u0646\u0627\u0639\u0645 \u0648\u0627\u0644\u062e\u0634\u0646":28,[u.c]:29,[u.x]:30,[u.f]:31,"\u0643\u062a\u0644 \u0627\u0644\u0637\u064a\u0646 \u0648\u0627\u0644\u062d\u0628\u064a\u0628\u0627\u062a \u0627\u0644\u0647\u0634\u0629 \u0641\u064a \u0627\u0644\u0631\u0643\u0627\u0645":32}
